package org.acme.checksum;

public class Adler {
    public long of(byte[] data) {
        java.util.zip.Adler32 adler = new java.util.zip.Adler32();
        adler.update(data);
        return adler.getValue();
    }
}

package org.acme.checksum;

public class Crc32c {
    public long of(byte[] data) {
        java.util.zip.CRC32C crc = new java.util.zip.CRC32C();
        crc.update(data);
        return crc.getValue();
    }
}

